import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, uniqueName, createWorkspace, inviteAndJoin } from './helpers';

// Minimal 1x1 transparent PNG, used to fill the mockup upload's file input.
const PNG_1x1 = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=',
  'base64',
);

async function uploadMockup(page: import('@playwright/test').Page, title: string) {
  await page.getByTestId('field-title').fill(title);
  await page.getByTestId('field-image').setInputFiles({
    name: 'mockup.png',
    mimeType: 'image/png',
    buffer: PNG_1x1,
  });
  await page.getByTestId('action-upload_mockup').click();
  await expect(page.getByTestId('item-mockup').filter({ hasText: title })).toBeVisible({ timeout: 10_000 });
}

async function addPin(page: import('@playwright/test').Page, offset: { x: number; y: number }, text: string) {
  const img = page.locator('img').first();
  await img.waitFor({ state: 'visible', timeout: 10_000 });
  const frame = img.locator('xpath=..');
  await frame.click({ position: offset });
  await page.getByTestId('field-text').fill(text);
  await page.getByTestId('action-add_pin').click();
  await expect(page.getByTestId('item-pin').filter({ hasText: text })).toBeVisible({ timeout: 10_000 });
}

test.describe(`teammate: mark a pin as resolved once it's been addressed`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`any teammate can resolve a pin, and the resolved status updates for everyone within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const teammateA = await ctxA.newPage();
    const teammateB = await ctxB.newPage();
    await loginViaHash(teammateA, 0);
    await loginViaHash(teammateB, 1);

    await inviteAndJoin(teammateA, teammateB);

    const title = uniqueName('mockup');
    await uploadMockup(teammateA, title);

    const text = uniqueName('pin-comment');
    await addPin(teammateA, { x: 40, y: 60 }, text);

    const rowA = teammateA.getByTestId('item-pin').filter({ hasText: text });

    await teammateB.getByTestId('item-mockup').filter({ hasText: title }).click();
    const resolvedRowB = teammateB.getByTestId('item-pin').filter({ hasText: text });
    await expect(resolvedRowB).toBeVisible({ timeout: 5_000 });

    // B, who did not author the pin, resolves it.
    await resolvedRowB.getByTestId('action-resolve_pin').click();

    // Resolved status updates for everyone within 5s: the resolve action is
    // only rendered for open pins, so its disappearance on both actors' views
    // is a stable, testid-driven proxy for "resolved" (no hardcoded label).
    await expect(resolvedRowB.getByTestId('action-resolve_pin')).toHaveCount(0, { timeout: 5_000 });
    await expect(rowA.getByTestId('action-resolve_pin')).toHaveCount(0, { timeout: 5_000 });

    await ctxA.close();
    await ctxB.close();
  });

  test(`resolving one pin never changes the resolved status of any other pin`, async ({ page }) => {
    await createWorkspace(page);
    const title = uniqueName('mockup');
    await uploadMockup(page, title);

    const textOne = uniqueName('pin-one');
    const textTwo = uniqueName('pin-two');
    await addPin(page, { x: 30, y: 30 }, textOne);
    await addPin(page, { x: 70, y: 70 }, textTwo);

    const rowOne = page.getByTestId('item-pin').filter({ hasText: textOne });
    const rowTwo = page.getByTestId('item-pin').filter({ hasText: textTwo });

    await rowOne.getByTestId('action-resolve_pin').click();
    await expect(rowOne.getByTestId('action-resolve_pin')).toHaveCount(0, { timeout: 5_000 });

    // The other pin's resolved status must be untouched: its resolve action
    // must still be present (it is only removed once that pin is resolved).
    await expect(rowTwo.getByTestId('action-resolve_pin')).toBeVisible();
  });
});
